const crypto = require('crypto');
const items = $input.all();
const out = [];

for (let i = 0; i < items.length; i++) {
  const json      = items[i].json;
  const secret    = $env.CHATWOOT_WEBHOOK_SECRET;
  const received  = json.headers['x-chatwoot-signature'];
  const timestamp = json.headers['x-chatwoot-timestamp'];

  let ok = false, expected = null, rawLen = null, rawPreview = null, err = null;
  try {
    const rawBuf = await this.helpers.getBinaryDataBuffer(i, 'data');   // 'data' = nombre de la prop binaria
    rawLen = rawBuf.length;
    rawPreview = rawBuf.toString('utf8').slice(0, 60);

    const signed = Buffer.concat([Buffer.from(`${timestamp}.`), rawBuf]);
    expected = 'sha256=' + crypto.createHmac('sha256', secret).update(signed).digest('hex');

    ok = !!received
      && expected.length === received.length
      && crypto.timingSafeEqual(Buffer.from(expected), Buffer.from(received));
  } catch (e) {
    err = String(e.message || e);
  }

  out.push({ json: { ...json, _hmac: { ok, expected, received, timestamp, rawLen, rawPreview, err } }, pairedItem: { item: i } });
}

return out;

// === DECIDIR — decide QUÉ hacer y arma la conversación (sin catálogo: eso lo inyecta 'Armar mensajes') ===
const webhookData = $('Chatwoot Webhook').first().json;
const body = webhookData.body;
const myMessageId = body.id;
const conversationId = body.conversation.id;
const accountId = body.account.id;

// F5: created_at robusto (unix int, string numérico o ISO) → siempre número
const num = (v) => {
  if (v == null) return 0;
  if (typeof v === 'number') return v;
  const n = Number(v);
  if (Number.isFinite(n)) return n;
  const t = Date.parse(v);
  return Number.isFinite(t) ? t : 0;
};
const myCreatedAt = num(body.created_at);

const historialJson = $('Get Historial').first().json;
const rawPayload = historialJson.payload;
const allMessages = Array.isArray(rawPayload) ? rawPayload : (rawPayload && rawPayload.messages ? rawPayload.messages : []);

const isIn = (m) => m.message_type === 'incoming' || m.message_type === 0;
const isOut = (m) => (m.message_type === 'outgoing' || m.message_type === 1) && !m.private;
const hasContent = (m) => m.content && String(m.content).trim().length > 0;

const sorted = allMessages.slice().sort((a, b) => num(a.created_at) - num(b.created_at));

// DEBOUNCE (F1): el "último" es el último ENTRANTE CON TEXTO.
// Una foto que llega después de la pregunta ya no gana el "soy el último".
const incoming = sorted.filter((m) => isIn(m) && hasContent(m));
const lastIncoming = incoming.length ? incoming[incoming.length - 1] : null;
if (lastIncoming && myMessageId && lastIncoming.id !== myMessageId) {
  return [{ json: { action: 'skip', reason: 'no-soy-el-ultimo', conversationId, accountId } }];
}

// IDEMPOTENCIA (F5): ya hay respuesta posterior a mi mensaje → no repito
const repliedAfter = sorted.some((m) => isOut(m) && num(m.created_at) > myCreatedAt);
if (repliedAfter) {
  return [{ json: { action: 'skip', reason: 'ya-respondido', conversationId, accountId } }];
}

// Ráfaga del cliente = entrantes con texto desde la última salida
let lastOutIdx = -1;
for (let i = sorted.length - 1; i >= 0; i--) {
  if (isOut(sorted[i])) { lastOutIdx = i; break; }
}
const burst = sorted.slice(lastOutIdx + 1).filter((m) => isIn(m) && hasContent(m)).map((m) => m.content);
// v8.1 NFC: ningun lado normaliza Unicode. Un teclado iOS/macOS que emita acentos
// DESCOMPUESTOS ("impresio\u0301n") hace fallar todo match con acento, en silencio y
// solo para algunos clientes. El catalogo esta en NFC; el mensaje del cliente, no.
const mergedUser = burst.join('\n').normalize('NFC');

if (!mergedUser) {
  return [{ json: { action: 'skip', reason: 'sin-texto-nuevo', conversationId, accountId } }];
}

// INJECTION: regex sobre el texto agregado (red barata; Tier-1 lo duplicará)
const INJECTION_PATTERNS = [
  /ignor[aá].*(instrucciones|reglas|rol)/i,
  /olvid[aá].*(instrucciones|reglas|rol)/i,
  /nuevo rol/i,
  /ignore (previous|instructions|your)/i,
  /system prompt/i,
  /jailbreak/i,
  /\bDAN\b/,
  /pretend you are/i,
  /do anything now/i,
  /forget your instructions/i
];
if (INJECTION_PATTERNS.some((p) => p.test(mergedUser))) {
  return [{ json: { action: 'injection', conversationId, accountId } }];
}

// PRIMER MENSAJE (F3): saludo enlatado SOLO si el texto es un saludo puro.
// Primer mensaje con pregunta → process (lo contesta el LLM).
const hasOutgoing = sorted.some(isOut);
function isGreetingOnly(text) {
  const t = (text || '')
    .toLowerCase()
    .replace(/[¡!¿?.,;:()"']/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
  if (!t) return false;
  const G = '(hola|holis|buenas|buen dia|buen día|buenos dias|buenos días|buenas tardes|buenas noches|hey|que tal|qué tal|como andas|cómo andás|como va|cómo va|todo bien)';
  const re = new RegExp('^' + G + '( ' + G + ')*$');
  return re.test(t);
}
if (!hasOutgoing && isGreetingOnly(mergedUser)) {
  return [{ json: { action: 'primer-mensaje', conversationId, accountId } }];
}

// CAP DE RESPUESTAS POR CONVERSACIÓN (ventana rodante 24h): tope duro para floods sostenidos.
const CAP_RESPUESTAS = 25;
const nowMs = Date.now();
const botOut = sorted.filter((m) => isOut(m) && hasContent(m));
const botOut24 = botOut.filter((m) => nowMs - num(m.created_at) < 86400000);
const CAP_MARK = 'muchos mensajes en esta conversación';
if (botOut24.length >= CAP_RESPUESTAS) {
  const capYaAvisado = botOut24.some((m) => String(m.content).toLowerCase().includes(CAP_MARK));
  if (capYaAvisado) {
    return [{ json: { action: 'skip', reason: 'cap-ya-avisado', conversationId, accountId } }];
  }
  return [{ json: { action: 'cap', conversationId, accountId } }];
}

// PROCESS: armar la conversación (sin system, sin catálogo). 'Armar mensajes' le prepende el system+catálogo.
// ¿ya se le avisó al cliente que el canal es solo informativo? (buscamos el email del negocio en salientes del bot)
const avisoDado = sorted.some((m) => isOut(m) && hasContent(m) && String(m.content).toLowerCase().includes('terminalgrafica@gmail.com'));
// Últimas 3 respuestas del bot → el LLM las usa para no repetirse (action noop)
const lastBotReplies = botOut.slice(-3).map((m) => String(m.content));

const conversation = [];
const history = sorted.slice(0, lastOutIdx + 1).slice(-6);
for (const m of history) {
  if (isIn(m) && hasContent(m)) {
    conversation.push({ role: 'user', content: m.content });
  } else if (isOut(m) && hasContent(m)) {
    conversation.push({ role: 'assistant', content: m.content });
  }
}
conversation.push({ role: 'user', content: mergedUser });

return [{ json: { action: 'process', conversation, userMessage: mergedUser, avisoDado, lastBotReplies, conversationId, accountId } }];

const input = $input.first().json;
const sd = $getWorkflowStaticData('global');
const TTL_MS = 10 * 60 * 1000; // 10 min — subilo si el catálogo casi no cambia

const fresh = sd.catalogo && sd.catalogoTs && (Date.now() - sd.catalogoTs) < TTL_MS;

return [{
  json: { ...input, _cacheHit: !!fresh, _catalogo: fresh ? sd.catalogo : null },
  pairedItem: { item: 0 },
}];

const input = $input.first().json;
const sd = $getWorkflowStaticData('global');
const fresh = input.catalogo; // la query devuelve { catalogo }

let cat;
if (fresh) {
  cat = fresh;
  sd.catalogo = cat;
  sd.catalogoTs = Date.now();
} else {
  // la query falló (onError=continueRegularOutput) → servimos cache viejo si hay
  cat = sd.catalogo || '(catalogo no disponible)';
}

return [{
  json: { _catalogo: cat, _cacheHit: false, _stale: !fresh },
  pairedItem: { item: 0 },
}];

const decidir = $('Decidir').first().json;
const conversation = decidir.conversation || [];
// v8.3b CASCADA DE ENTRADA. Este nodo tiene TRES padres y solo dos traen el
// catalogo en el item: '¿Cache Catalogo Fresco?[out0]' y 'Guardar Cache Catalogo'.
// El tercero —'Forzar Ruta General', la ruta del `action volver`— recibe el item de
// Parsear Respuesta, que NO devuelve _catalogo: el throw de abajo abortaba el turno
// entero. El cliente no recibia nada y no quedaba fila en bot.decisiones, o sea que
// desde la base el turno no existio. Se busca en los nodos de cache, que en ese
// camino ya corrieron en el mismo turno.
let catalogo = $input.first().json._catalogo || '';
for (const fuente of ['Guardar Cache Catálogo', 'Chequear Cache Catálogo']) {
  if (catalogo) break;
  try { catalogo = String($(fuente).first().json._catalogo || ''); } catch (e) { /* no corrio */ }
}
if (!catalogo) catalogo = '(catalogo no disponible)';

if (!String(catalogo).trim() || String(catalogo).trim() === '(catalogo no disponible)') {
  throw new Error('Catalogo no disponible: se aborta el turno para no contestar sin mundo cerrado. Revisar Get Catalogo / cache.');
}

// C2: ruta deterministica desde la telemetria (Get Ruta Cotizador). Si la ultima
// accion de ESTA conversacion fue una pregunta de cotizacion reciente, el turno lo
// atiende el prompt ESPECIALISTA con solo el catalogo cotizable. 'forzarGeneral'
// (action volver del especialista) pisa la ruta -> cota estructural de 1 vuelta.
const RUTA_TTL_SEG = 1800;
let rutaCotizador = false;
try {
  // v9: las filas de silencio ('noop', de Log Silencio) NO cuentan como la ultima
  // accion de la conversacion — son ruido de debounce/anti-loop, no un turno.
  const r = (($('Get Ruta Cotizador').all() || []).map((i) => i.json)
    .find((f) => f && f.accion !== 'noop')) || {};
  rutaCotizador = ['repregunto', 'informo_capacidad'].includes(r.accion) && Number(r.edad_seg) < RUTA_TTL_SEG;
} catch (e) { rutaCotizador = false; }
if ($input.first().json.forzarGeneral === true) rutaCotizador = false;

let systemPrompt;
if (rutaCotizador) {
  // catalogo cotizable derivado del MISMO cache (coherencia con main garantizada):
  // headers RUBRO + lineas '- ' con alguna opcion con precio (*). Sin la leyenda
  // del main: el prompt cotizador trae su propio framing corto.
  const out = [];
  let header = null;
  for (const l of String(catalogo).split('\n')) {
    if (/^RUBRO:/i.test(l.trim())) { header = l; continue; }
    if (l.trim().startsWith('-') && l.includes('*')) {
      if (header) { if (out.length) out.push(''); out.push(header); header = null; }
      out.push(l);
    }
  }
  systemPrompt = $('Prompt Cotizador').first().json.promptCotizador.replace('__CATALOGO__', out.join('\n') || '(sin lineas cotizables)');
} else {
  systemPrompt = $('System Prompt').first().json.systemPrompt.replace('__CATALOGO__', catalogo);
}

// v8.2 AVISO DE CANAL DURABLE. `decidir.avisoDado` es un includes() del mail
// sobre la ventana SIN paginar que devuelve Chatwoot: en una conversacion larga
// el aviso se cae de esa ventana y el bot lo repite (salio 4 veces en la ronda
// del 27). bot.decisiones SI es durable por conversacion, y el router ya la
// consulta. Cualquiera de las dos fuentes que diga que si, vale.
let avisoDado = !!decidir.avisoDado;
try { if ($('Get Ruta Cotizador').all().some((it) => (it.json || {}).aviso_dado === true)) avisoDado = true; } catch (e) {}
const avisoNote = avisoDado
  ? 'ESTADO INTERNO (no lo menciones textualmente): al cliente YA se le avisó que este canal es solo informativo y que los pedidos se hacen por email. NO repitas ese aviso; seguí contestando normal sus consultas.'
  : 'ESTADO INTERNO (no lo menciones textualmente): al cliente TODAVÍA no se le avisó sobre el canal informativo/email.';

// v9 VERIFICADOR DE SILENCIO — 2ª vuelta. Estos dos campos vienen del rescate.
let reintentoSilencio = false, pendienteVerif = '';
try {
  const sv = $input.first().json;
  reintentoSilencio = sv.reintentoSilencio === true;
  pendienteVerif = typeof sv.pendienteVerif === 'string' ? sv.pendienteVerif : '';
} catch (e) { reintentoSilencio = false; }

// v9 PREGUNTA PENDIENTE (decision Martin 2026-07-28). El turno anterior pudo
// terminar preguntando algo concreto ('¿cuantos necesitas?'). Sin esto, la
// respuesta corta del cliente ('3') llega sin referente y el especialista la
// manda a sin_match: 'No me quedo claro que producto necesitas'.
// Sale de bot.decisiones.senales, que Get Ruta Cotizador ya filtra por
// conversation_id -> imposible que se cruce con otra conversacion.
// Se saltean las filas de SILENCIO. 'Log Silencio' inserta en la misma tabla con
// accion 'noop' y sin columna senales, y un mensaje de ráfaga (WhatsApp: el
// cliente manda '3' y 'gracias' seguidos) genera una: el debounce descarta el
// primero con action skip -> fila noop -> tapaba filas[0] y la pendiente
// desaparecia. Lo cazo el consejo del 28.
let pendNote = '';
try {
  const filas = ($('Get Ruta Cotizador').all() || []).map((i) => i.json);
  const f0 = filas.find((f) => f && f.accion !== 'noop');
  if (f0 && Number(f0.edad_seg) < RUTA_TTL_SEG) {
    let s = f0.senales;
    if (typeof s === 'string') { try { s = JSON.parse(s); } catch (e) { s = null; } }
    const pd = s && s.pendiente;
    if (pd && pd.tipo) {
      // Todos los tipos que emite ARP tienen su frase: sin esto caian al fallback
      // crudo y salia 'le preguntaste al cliente producto' (consejo del 28).
      const QUE = { cantidad: 'CUANTAS unidades necesita', nicho: 'para que lo necesita',
                    opcion: 'CUAL de las opciones que le ofreciste quiere',
                    producto: 'QUE producto necesita', faz: 'si lo quiere simple o doble faz' };
      pendNote = 'ESTADO INTERNO (no lo menciones textualmente): en tu mensaje anterior le preguntaste al cliente '
        + (QUE[pd.tipo] || pd.tipo) + (pd.producto ? ', sobre ' + pd.producto : '')
        + '. Si este mensaje es corto o es solo un numero, ES LA RESPUESTA A ESA PREGUNTA: usala y segui, no vuelvas a preguntar que producto es.';
    }
  }
} catch (e) { pendNote = ''; }

const lastBotReplies = decidir.lastBotReplies || [];
const FALTA_DICE = {
  precio: ' Lo que falta es el PRECIO de lo que preguntó.',
  plazo: ' Lo que falta es el PLAZO de entrega.',
  disponibilidad: ' Lo que falta es si eso lo hacemos o no.',
  opciones: ' Lo que falta son las OPCIONES que tenemos.',
  otro: '',
};
const repeatNote = reintentoSilencio
  ? 'ESTADO INTERNO (no lo menciones textualmente): ya intentaste responder este mensaje y te quedaste callado, pero el cliente TODAVÍA no tiene lo que pidió. NO uses action noop en este turno.'
    + (FALTA_DICE[pendienteVerif] || '')
    + ' Contestá lo que te pidió el cliente. Si es un precio, usá action precio; si el dato no existe en el catálogo, decilo con action answer en vez de callarte.'
  : lastBotReplies.length
  ? 'ESTADO INTERNO (no lo menciones): tus últimas respuestas en esta conversación fueron:  ' + lastBotReplies.map((r, i) => '[' + (i + 1) + '] ' + r).join('   ///   ') + '.  Si tu respuesta no agregaría nada nuevo (misma intención o información) respecto de estas, y el cliente no sumó una pregunta ni un dato nuevo, respondé con action noop.'
  : 'ESTADO INTERNO: todavía no diste ninguna respuesta en esta conversación.';

// el especialista no maneja email/cierre -> avisoNote solo en ruta general
// v8.1 ANTI-LOOP. Los guards deterministicos tienen que comparar contra el BORRADOR
// previo, no contra lo que salio por Chatwoot: desde el compositor eso es texto
// parafraseado y nunca vuelve a coincidir consigo mismo. Log Turno ya guarda el
// borrador; Get Ruta Cotizador ahora trae los ultimos 3.
let borradoresPrevios = [];
try {
  borradoresPrevios = $('Get Ruta Cotizador').all()
    .map((it) => (it.json || {}).borrador)
    .filter((s) => typeof s === 'string' && s.trim());
} catch (e) { borradoresPrevios = []; }

// v8.1 CONSERVACION DE NOMBRE (gate del compositor). Los nombres tal como los lista
// el catalogo, para poder detectar que el compositor nombre OTRO producto real.
const nombresCatalogo = String(catalogo).split('\n')
  .filter((l) => l.trim().startsWith('- '))
  .map((l) => l.trim().slice(2).split(' — ')[0].trim())
  .filter(Boolean);

// El pendNote va DESPUES del repeatNote a proposito: el repeatNote empuja al noop
// ('si no agregas nada nuevo, callate') y este lo contrapesa diciendo que si hay
// algo que hacer con el mensaje. El ultimo system message pesa mas.
const extras = [{ role: 'system', content: repeatNote }];
if (pendNote) extras.push({ role: 'system', content: pendNote });
const llmMessages = rutaCotizador
  ? [{ role: 'system', content: systemPrompt }, ...extras, ...conversation]
  : [{ role: 'system', content: systemPrompt }, { role: 'system', content: avisoNote }, ...extras, ...conversation];

// v8.3b: se republica el catalogo. Armar Prompt Aclarador lo leia de 'Guardar
// Cache Catalogo', que SOLO corre en cache MISS: con el TTL de 10 min el caso
// normal es HIT, ese nodo no corrio, $() tira y su catch dejaba el catalogo en ''.
// El Aclarador terminaba recibiendo 'lista cerrada, es TODO lo que existe: (sin
// lineas cotizables)' y contestaba 'nada' -> mail. Correcto dada esa lista, pero
// la lista estaba vacia por un bug de cableado (conversacion 354, 2026-07-28).
// Este nodo es el unico que tiene el catalogo garantizado en TODO turno (si falta,
// tira en la linea 5) y corre siempre antes del Aclarador.
// v9: el flag del verificador viaja por acá o la cota anti-ciclo no existe:
// Armar Mensajes LLM reconstruye el sobre desde 'Decidir' y perdía el campo que
// puso 'Aplicar Verificador' aguas arriba.
return [{ json: { ...decidir, avisoDado, llmMessages, rutaCotizador, borradoresPrevios, nombresCatalogo, reintentoSilencio, pendienteVerif, _catalogo: catalogo }, pairedItem: { item: 0 } }];

// Parsea la salida JSON del LLM de forma tolerante. Fallback seguro = handoff.
const decidir = { ...$('Decidir').first().json };
// v8.2 Un noop no dejaba NINGUNA fila: los tres origenes (el LLM lo emitio, el
// reply vino vacio, el anti-loop lo forzo) eran indistinguibles desde la base, y
// por eso 'necesito anillar 3 apuntes' y 'Hola?' se perdieron sin motivo.
let noopOrigen = 'llm';
// v8.2: el aviso de canal es UNA vez por CONVERSACION, y la senal de Decidir se
// cae con la paginacion del historial de Chatwoot. Armar Mensajes LLM la cruza
// contra bot.decisiones; si cualquiera de las dos dice que ya se aviso, vale.
try { if ($('Armar Mensajes LLM').first().json.avisoDado) decidir.avisoDado = true; } catch (e) {}

let raw = '';
try { raw = $input.first().json.choices[0].message.content || ''; } catch (e) { raw = ''; }

let txt = String(raw).trim();
// sacar posibles fences ```json ... ```
if (txt.startsWith('```')) {
  txt = txt.replace(/^```[a-zA-Z]*\s*/, '').replace(/```\s*$/, '').trim();
}

// El LLM a veces agrega basura DESPUES del objeto ('...}\n"}'): el objeto esta
// bien formado pero JSON.parse del string entero falla y se pierde el turno.
// Se extrae el primer objeto BALANCEADO, respetando strings y escapes.
const primerJson = (t) => {
  const i = String(t).indexOf('{');
  if (i < 0) return null;
  let d = 0, str = false, esc = false;
  for (let k = i; k < t.length; k++) {
    const c = t[k];
    if (esc) { esc = false; continue; }
    if (c === '\\') { if (str) esc = true; continue; }
    if (c === '"') { str = !str; continue; }
    if (str) continue;
    if (c === '{') d++;
    else if (c === '}') { d--; if (d === 0) return t.slice(i, k + 1); }
  }
  return null;
};
const parseTolerante = (t) => {
  try { return JSON.parse(t); }
  catch (e) { const j = primerJson(t); if (!j) throw e; return JSON.parse(j); }
};

const nfc = (s) => typeof s === 'string' ? s.normalize('NFC') : s;
// v8.3 (decisión Martin 2026-07-27): el bot muestra todas las opciones de una y
// nunca repregunta para desambiguar. El cupo dejó de ser "cuánto tolera el lector"
// (esa premisa murió cuando el compositor empezó a comprimir listas en prosa) y
// pasó a ser "cuánto entra en un mensaje". 4 → 8.
const CUPO_OPCIONES = 8;
let action = 'handoff', reply = '', motivo = '', producto = '', variante = '', mas = [], cantidad = null, paginas = null, copias = null, flags = [], opcionesObj = null;
try {
  const obj = parseTolerante(txt);
  action = String(obj.action || '').toLowerCase();
  reply = typeof obj.reply === 'string' ? obj.reply : '';
  motivo = typeof obj.motivo === 'string' ? obj.motivo : '';
  if (action === 'precio') {
    producto = typeof obj.producto === 'string' ? nfc(obj.producto.trim()) : '';
    variante = nfc((typeof obj.variante === 'string' ? obj.variante : '').replace(/\*+\s*$/, '').trim());
    if (Array.isArray(obj.mas)) {
      mas = obj.mas.slice(0, 2).map((m) => {
        const mc = typeof m?.cantidad === 'string' && /^\d{1,6}$/.test(m.cantidad.trim()) ? Number(m.cantidad.trim()) : m?.cantidad;
        return {
          producto: typeof m?.producto === 'string' ? nfc(m.producto.trim()) : '',
          variante: nfc((typeof m?.variante === 'string' ? m.variante : '').replace(/\*+\s*$/, '').trim()),
          cantidad: Number.isInteger(mc) && mc >= 1 && mc <= 999999 ? mc : null,
        };
      }).filter((m) => m.producto);
    }
    const entero = (val, max) => {
      const c = typeof val === 'string' && /^\d{1,6}$/.test(val.trim()) ? Number(val.trim()) : val;
      return Number.isInteger(c) && c >= 1 && c <= max ? c : null;
    };
    cantidad = entero(obj.cantidad, 999999);
    paginas = entero(obj.paginas, 5000);
    copias = entero(obj.copias, 1000);
    // copias sin paginas: no hay unidad base para multiplicar -> se ignoran ambos
    if (copias !== null && paginas === null) { copias = null; flags.push('copias_sin_paginas'); }
  }
  if (action === 'opciones') {
    const prods = Array.isArray(obj.productos) ? obj.productos.slice(0, CUPO_OPCIONES).map((x) => typeof x === 'string' ? nfc(x.trim()) : '').filter(Boolean) : [];
    const FALTAN_OK = ['cantidad', 'paginas', 'copias', 'producto', 'opcion'];
    opcionesObj = { productos: prods, faltan: Array.isArray(obj.faltan) ? obj.faltan.filter((x) => FALTAN_OK.includes(x)) : [] };
  }
  if (!['answer', 'handoff', 'noop', 'precio', 'opciones', 'volver'].includes(action)) action = 'handoff';
} catch (e) {
  action = 'handoff'; reply = ''; motivo = 'respuesta del modelo ilegible';
}
// C2: 'volver' solo vale viniendo del especialista; en ruta general se descarta a
// handoff (cota estructural del ciclo volver->general: 1 vuelta por ejecucion).
let rutaCot = false;
try { rutaCot = $('Armar Mensajes LLM').first().json.rutaCotizador === true; } catch (e) { rutaCot = false; }
if (action === 'volver' && !rutaCot) { action = 'handoff'; motivo = 'action volver fuera de ruta cotizador'; }
if (action === 'volver' || action === 'opciones') reply = '';
if (action === 'handoff' && !motivo.trim()) motivo = 'sin motivo especificado';

// answer sin texto = no hay nada que mandar → silencio (noop), NO handoff (no escalamos ruido a un humano)
if (action === 'answer' && !reply.trim()) {
  action = 'noop'; noopOrigen = 'reply-vacio';
}

// BACKSTOP PRIMERA MENCION: si el mail ya se menciono y el cliente NO lo pide, no repetir la direccion.
const pideMail = /mail|correo|casilla|direcci/i.test(decidir.userMessage || '');
if (decidir.avisoDado && !pideMail && reply) {
  // Cascada de especifico a pelado (hallazgo R1 ronda 2: "a nuestro email nuestro mail").
  // Absorbe el lead-in que el LLM ya puso (a/al + nuestro/el/la + email/mail/correo/
  // casilla/direccion (de correo) + ':' opcional) para no dejar la frase duplicada.
  reply = reply
    .replace(/(?:por\s+(?:e-?mail|mail|correo)\s+)?\b(?:a|al)\s+(?:(?:nuestr[oa]|el|la)\s+)?(?:(?:e-?mail|mail|correo|casilla|direcci[oó]n(?:\s+de\s+(?:correo|e-?mail|mail))?)\s*:?\s*)?terminalgrafica@gmail\.com/gi, 'a nuestro mail')
    .replace(/\b(?:(?:nuestr[oa]|el|la)\s+)?(?:e-?mail|mail|correo|casilla|direcci[oó]n(?:\s+de\s+(?:correo|e-?mail|mail))?)\s*:?\s*terminalgrafica@gmail\.com/gi, 'nuestro mail')
    .replace(/terminalgrafica@gmail\.com/gi, 'nuestro mail');
}

// BACKSTOP DETERMINISTICO ANTI-REPETICION
// Red de seguridad para cuando el LLM NO se auto-silencia (action noop) y repite textual.
// Normaliza y compara la respuesta candidata contra las ultimas del bot (Decidir.lastBotReplies, ultimas 3).
// Umbral 2 a proposito (no 1): protege el repetir legitimo a pedido ("no me llego, repetimelo").
// Si el bot YA dijo esto ~igual 2+ veces recientes, un 3er envio es un loop -> noop.
const MAX_REPETICIONES = 2;
const normRep = (s) => String(s || '')
  .toLowerCase()
  .replace(/[*_`~#>\-]/g, ' ')
  .replace(/[¡!¿?.,;:()"']/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

if (action === 'answer' && reply.trim()) {
  // v8.1: contra el BORRADOR previo, no contra el texto compuesto (ver Armar Mensajes LLM).
  let recientes = [];
  try { recientes = $('Armar Mensajes LLM').first().json.borradoresPrevios || []; } catch (e) { recientes = []; }
  const cand = normRep(reply);
  if (cand) {
    const repeticiones = recientes.filter((r) => normRep(r) === cand).length;
    if (repeticiones >= MAX_REPETICIONES) {
      action = 'noop'; noopOrigen = 'anti-loop';
    }
  }
}

// RAMA PRECIO — backstops deterministicos (el LLM NUNCA tipea el numero):
// - {{PRECIO}} debe aparecer exactamente una vez en el template;
// - si el LLM escribio un patron de plata igual, se descarta su texto (plantilla fija).
// producto/variante vacios NO degradan aca: Get Precio dara 0 filas -> fallback email.
let precio = null;
if (action === 'precio') {
  const template = reply;
  const marcas = (template.match(/\{\{PRECIO\}\}/g) || []).length;
  const plataRe = /(\$\s*\d)|(\d[\d.,]*\s*(pesos|ars)\b)/i;
  const forzarPlantilla = marcas !== 1 || plataRe.test(template.replace(/\{\{PRECIO\}\}/g, ''));
  precio = { producto, variante, template, forzarPlantilla, mas, cantidad, paginas, copias, flags };
  // E: ¿el nombre que emitio el LLM EXISTE en el catalogo? El set sale del mismo
  // cache que arma el prompt, asi que nunca puede estar mas viejo que el catalogo.
  // Fail-open: sin catalogo el chequeo no corre (cache frio > cliente rechazado).
  try {
    const cat = $('Armar Mensajes LLM').first().json.nombresCatalogo || [];
    if (cat.length && precio && precio.producto) {
      const norm = (s) => String(s || '').toLowerCase()
        .replace(/[áéíóúü]/g, (c) => ({ 'á': 'a', 'é': 'e', 'í': 'i', 'ó': 'o', 'ú': 'u', 'ü': 'u' }[c]))
        .replace(/ñ/g, 'n').replace(/\s+/g, ' ').trim();
      const set = new Set(cat.map(norm));
      if (!set.has(norm(precio.producto))) {
        precio.flags = (precio.flags || []).concat('producto_inventado');
      }
    }
  } catch (e) { /* fail-open */ }
  reply = '';
}

if (action === 'noop') reply = '';

return [{
  json: {
    action, reply, motivo, noopOrigen, precio, opciones: opcionesObj,
    conversationId: decidir.conversationId,
    accountId: decidir.accountId,
    userMessage: decidir.userMessage,
  },
  pairedItem: { item: 0 },
}];

// Rama Fail del Guardrails Tier-2. Distingue una VIOLACIÓN REAL (jailbreak/topical
// flaggeado por el modelo) de una CAÍDA del modelo-guard (executionFailed) o un item
// de error del nodo. Fail-open ante caída: no penaliza, deja seguir al LLM principal
// (que ya degrada a handoff si OpenRouter está caído).
const j = $input.first().json;
const checks = Array.isArray(j.checks) ? j.checks : [];
const violated = checks.filter((c) => c && c.triggered && !c.executionFailed);
const realViolation = violated.length > 0;
// reason = nombre del guard que disparó (jailbreak | topicalAlignment)
const reason = realViolation ? String(violated[0].name || 'tier2') : 'model_error';

const b = $('Chatwoot Webhook').first().json.body;
const sid = b.sender?.id ?? b.conversation?.meta?.sender?.id ?? '';
const decidir = $('Decidir').first().json;

return [{
  json: {
    realViolation,
    reason,
    senderKey: String(sid),
    conversationId: decidir.conversationId,
    accountId: decidir.accountId,
    userMessage: decidir.userMessage,
  },
  pairedItem: { item: 0 },
}];

// v7 COTIZADOR — Rama precio: inyeccion deterministica desde bot.variantes (mismas filas que el
// motor del mostrador — nunca recalcular = no precio fantasma). El LLM nunca ve
// reglas ni tipea montos. Escalera deterministica POR ITEM (main + hasta 2
// extras via campo 'mas'), cada uno con su propio estado:
//   override / 2+ reglas de cantidad / precio $0  -> sin numero (email)
//   exactamente 1 regla de cantidad               -> tabla de rangos verbatim + caveat
//   sin reglas                                    -> numero limpio
//   resto (descuentos/adicionales)                -> numero de lista + caveat neutro
const parsear = $('Parsear Respuesta').first().json;
const decidir = { ...$('Decidir').first().json };
// v8.2: el aviso de canal es UNA vez por CONVERSACION, y la senal de Decidir se
// cae con la paginacion del historial de Chatwoot. Armar Mensajes LLM la cruza
// contra bot.decisiones; si cualquiera de las dos dice que ya se aviso, vale.
try { if ($('Armar Mensajes LLM').first().json.avisoDado) decidir.avisoDado = true; } catch (e) {}
const p = parsear.precio || {};
// El gemelo 'Armar Respuesta Precio 2' (2ª pasada tras el Aclarador) es IDENTICO
// salvo estas dos cosas: SEGUNDA_PASADA=true y la fuente de slots ('Parsear
// Respuesta' -> 'Aplicar Aclarador'). Se genera programaticamente; el harness
// testea AMBOS para que no driftee. NO editar uno sin el otro.
const SEGUNDA_PASADA = false;
const TRIGGERS_ACLARADOR = ['fallback: sin_match', 'fallback: ambiguo', 'fallback: faz_incoherente', 'fallback: producto_nicho', 'fallback: producto_incoherente'];
// Item de error de Get Precio (onError continueRegularOutput): distinguir fallo SQL
// de un no-match real en la telemetria (el cliente recibe el mismo fallback igual).
const errItem = $input.all().find((i) => i.json && i.json.error);

// v7 r4: ventana de los ultimos 3 mensajes ENTRANTES (incluido el actual) para los
// guards que un solo turno no cubre (suite-5 real: el bookcel quedo en el mensaje
// anterior y el follow-up recibio total).
const PAPEL_RE = /book\s*cell?|(?:papel(?:es)?|hojas?)\s+(?:de\s+)?(?:color(?:es)?|celestes?|amarill\w*|rosad\w*|rosas?|verdes?|azul(?:es)?|roj[ao]s?|naranjas?|violetas?|lilas?|cremas?|fucsias?|gris(?:es)?|negr[ao]s?)|m[aá]s\s+grueso|mejor\s+papel|papel\s+mejor/i;
const CORRECCION_RE = /(?:papel|hoja)s?\s+(?:com[uú]n|normal|blanc[oa]|de\s+siempre)|sin\s+(?:el\s+)?(?:bookcel|color)/i;
const msgsCliente = (Array.isArray(decidir.conversation) ? decidir.conversation : []).filter((m) => m && m.role === 'user').map((m) => String(m.content || ''));
const ultimos3 = msgsCliente.slice(-3);
const msgActual = String(decidir.userMessage || '');
const hitPapelActual = PAPEL_RE.test(msgActual);
const hitPapelHistorial = ultimos3.slice(0, -1).some((t) => PAPEL_RE.test(t));
// hit del turno actual dispara SIEMPRE (negacion ciega aceptada, r3); hit del
// historial se suprime si el cliente se CORRIGE explicito en el turno actual.
const papelEspecialHit = hitPapelActual || (hitPapelHistorial && !CORRECCION_RE.test(msgActual));
// Gramajes ANCLADOS por el cliente (nunca numeros pelados: '120 paginas' no es gramaje).
const extraerGramajes = (txt) => {
  const out = new Set(); let m;
  const re1 = /\b(\d{2,3})\s*(?:gr|grs|gramos)\b/gi;
  const re2 = /obra\s+(?:de\s+)?(\d{2,3})\b/gi;
  while ((m = re1.exec(txt))) out.add(m[1]);
  while ((m = re2.exec(txt))) out.add(m[1]);
  return out;
};
const gramajesCliente = extraerGramajes(ultimos3.join('\n') || msgActual);
// r6 GUARD FAZ INVERSA (caso 14 ronda 2): cliente pidio SIMPLE faz y la fila
// resuelta es doble faz -> numero equivocado con cara de correcto -> repregunta.
const pidioSF = /simple\s*faz|\bs\s*\/\s*f\b|una\s+sola\s+(?:cara|faz)|de\s+un\s+solo\s+lado/i.test(msgActual);
// r6 GUARD NICHO (casos 4/5 ronda 2): producto de precio especial por rubro
// (medicina) solo aplica si el cliente nombro el nicho en la ventana.
// v8: el nicho sale del ATRIBUTO curado (E0) y la regex por nombre queda de
// fallback para filas sin atributos. La promo inmobiliarias entra aca: es solo
// para inmobiliarias (Martin) y hoy aparece ante cualquier consulta de carteles.
const NICHOS = [
  { clave: 'medicina', re: /medicin/i, pregunta: '¿Es material de medicina (módulos/apuntes de la facultad)? Tenemos un precio especial para eso. Si no, contame qué querés imprimir y te paso las opciones.' },
  { clave: 'inmobiliarias', re: /inmobiliari|inmueble|cartel(?:es)?\s+de\s+(?:venta|alquiler)|(?:vend|alquil)\w*\s+(?:una?\s+)?(?:casa|depto|departamento|propiedad|terreno|lote)/i, pregunta: '¿Es para una inmobiliaria? Tenemos una promoción para ese caso. Si no, contame qué cartel necesitás y te paso las opciones.' },
];
// v8: atributos EFECTIVOS de la fila. La vista bot.variantes ya mergea
// producto || variante, asi que aca solo hay que parsear.
// F3: ¿el cliente NOMBRO el valor de este eje? Se compara contra su mensaje, no
// contra la fila. Reusa los detectores que ya existian (gramajes, faz).
const EJES_CLIENTE = ['gramaje_gr', 'papel', 'material', 'tamano', 'faz', 'color', 'acabado', 'cobertura'];
const normMsg = (s) => String(s || '').toLowerCase()
  .replace(/[áéíóúü]/g, (c) => ({ 'á': 'a', 'é': 'e', 'í': 'i', 'ó': 'o', 'ú': 'u', 'ü': 'u' }[c])).replace(/ñ/g, 'n');
const dijoValor = (msgN, clave, val) => {
  if (val === null || val === undefined) return false;
  if (Array.isArray(val)) return val.some((v) => dijoValor(msgN, clave, v));
  const v = normMsg(val);
  if (clave === 'color') return v === 'bn'
    ? /\bb\s*\/?\s*n\b|blanco\s+y\s+negro|monocrom|\bnegro\b/.test(msgN)
    : /\bcolor(?:es)?\b/.test(msgN);
  if (clave === 'faz') return v === 'doble'
    ? /doble\s*faz|\bd\s*\/\s*f\b|frente\s*y\s*dorso|ambas\s+caras|dos\s+lados/.test(msgN)
    : /simple\s*faz|\bs\s*\/\s*f\b|un\s+solo\s+lado|una\s+(?:sola\s+)?cara/.test(msgN);
  if (clave === 'gramaje_gr') return new RegExp('(?:^|[^0-9])' + v + '(?![0-9])').test(msgN);
  if (!/[a-z0-9]/.test(v)) return false;
  return new RegExp('(?:^|[^a-z0-9])' + v.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '(?![a-z0-9])').test(msgN);
};

const atrDe = (row) => {
  let a = row && row.atributos;
  if (typeof a === 'string') { try { a = JSON.parse(a); } catch (e) { a = null; } }
  return a && typeof a === 'object' && !Array.isArray(a) ? a : {};
};
const nichoDe = (nombre, row) => {
  const k = atrDe(row).nicho;
  if (k) return NICHOS.find((n) => n.clave === k) || null;
  return NICHOS.find((n) => n.re.test(String(nombre || ''))) || null;
};
const ventanaCliente = msgsCliente.join('\n') || msgActual;
// v8 REGLA DE SUSTANTIVO (bug V2). En los productos que se venden POR TRABAJO el
// numero del cliente multiplica SOLO si cuenta trabajos ("3 apuntes anillados"),
// nunca material ("anillado para 120 hojas" daba 120 x $4.200 = $504.000 en la
// ronda 4). Direccion segura: sin prueba de que cuenta trabajos, NO multiplica.
const TRABAJO_RE = /anillad|encuadernad|refilad|abrochad|emblocad|numerad|armad|plastificad|trabajo|libro|apunte|m[oó]dulo|cuadernill|revista|informe|tesis|carpeta|ejemplar|copia|juego/i;
const MATERIAL_RE = /hoja|p[aá]gina|carilla|impresion|impresi[oó]n|fotocopia|original|archivo|foja/i;
const cuentaTrabajos = (txt, num) => {
  if (!Number.isInteger(num)) return false;
  const re = new RegExp('(?:^|[^0-9])' + num + '(?![0-9])([^.,;\\n]{0,40})', 'i');
  const m0 = re.exec(String(txt || ''));
  if (!m0) return false;
  if (MATERIAL_RE.test(m0[1])) return false;
  return TRABAJO_RE.test(m0[1]);
};

const MAX_RANGOS = 6;
// La leyenda vieja iba INLINE y entre parentesis: '... sale $800,00 (precio de
// lista; el precio final del trabajo te lo confirma el equipo).' Ilegible en
// WhatsApp. Decision de Martin (r7 §0, 2026-07-25): oracion aparte y corta.
// CAVEAT/CAVEAT_CORTO quedan vacios y el cierre se agrega UNA vez al final, asi
// no se repite por item en los multi-item.
const CAVEAT = '';
const CIERRE = ' Los pedidos se hacen por mail a terminalgrafica@gmail.com o en el local; este canal es solo informativo.';
// Anti-eco: si el template del LLM ya dice "precio de lista", el caveat inyectado
// no lo repite (version corta). La parte esencial (el final lo confirma el equipo)
// queda SIEMPRE pegada al numero.
const CAVEAT_CORTO = '';
// El 'c/u' colgado es la causa raiz de la mentira de unidad: en "Por 200 paginas
// ... sale $88 c/u" lo mas cercano gramaticalmente son las PAGINAS, y el precio es
// por HOJA. ARP tiene el dato (unidad_venta) y no lo estaba diciendo.
const UNIDAD_FRASE = { hoja: 'por hoja', pagina: 'por página', unidad: 'c/u', m2: 'por m²',
  metro: 'por metro', trabajo: 'por trabajo', pack: 'por pack', millar: 'por millar' };
// v8.2 El sustantivo de la unidad, para el encabezado de la tabla de rangos
// ("precio de lista por hoja segun cantidad"), donde UNIDAD_FRASE no encaja.
const UNIDAD_NOMBRE = { hoja: 'hoja', pagina: 'página', unidad: 'unidad', m2: 'm²',
  metro: 'metro', trabajo: 'trabajo', pack: 'pack', millar: 'millar' };
// v8.2 Unidades que CAMBIAN el sentido del monto y por eso se dicen aunque no
// haya total. 'c/u' y 'por trabajo' son el default implicito: decirlos suena a
// formulario y no agrega informacion.
const UNIDAD_EXPLICITA = { hoja: 1, pagina: 1, m2: 1, metro: 1, millar: 1, pack: 1 };
const fmt = (n) => '$' + new Intl.NumberFormat('es-AR', { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(Number(n));
// F3: una variante "legible" tiene al menos una letra o digito (la clase "." no se
// muestra). "única" es la etiqueta SINTETICA que el catalogo publica para los
// mono-variante (no es un nombre real) -> tampoco se muestra.
const normNV = (s) => String(s || '').toLowerCase().replace(/[áéíóúñ]/g, (c) => ({ 'á': 'a', 'é': 'e', 'í': 'i', 'ó': 'o', 'ú': 'u', 'ñ': 'n' }[c])).replace(/\s+/g, ' ').trim();
const nombreVar = (v, canon) => {
  const s = String(v || '').trim();
  if (!/[a-z0-9]/i.test(s)) return '';
  if (/^[uú]nica$/i.test(s)) return '';
  // I5 (ronda suite-5): variante que se llama IGUAL que el producto -> ocultarla
  // (si no, el render duplica: 'La opción X de X').
  if (canon && normNV(s) === normNV(canon)) return '';
  return s;
};

// v8.3b: las filas vienen de Aplicar Filtro (el mismo SQL que eligio el producto),
// no de un Get Precio que volvia a resolver por nombre. Fallback a \$input para el
// gemelo de 2a pasada, que sigue colgando de Get Precio 2.
let todo = [], desdeFiltro = false;
try {
  const ff = $('Aplicar Filtro').first().json.filasPrecio;
  if (Array.isArray(ff) && ff.length) { todo = ff.filter((r) => r && r.precio_lista !== undefined); desdeFiltro = todo.length > 0; }
} catch (e) { todo = []; desdeFiltro = false; }
// v9.2: desde el bloque 12d, `$input` de la 1a pasada puede traer la fila del
// HERMANO (la salida de `Get Precio`), que no es un candidato: tomarla como tal
// cotizaria el producto equivocado. Se descarta POR LO QUE ES —la fila que
// coincide con el uuid que ARP mismo pidio— y no anulando la fuente: el fallback
// a $input sigue vivo para cuando `Aplicar Filtro` no trae nada, que es para lo
// que existe. Anularlo entero dejaba a la 1a pasada sin candidatos.
// Se distingue por ORIGEN, no por uuid: las filas que trajo `Get Precio` son, por
// construccion, las del hermano — es el unico trabajo que ese nodo hace ahora.
// Comparar contra `hermanoPide` no serviria: esa variable se declara 300 lineas
// mas abajo (junto al guard) y aca seria un uso antes de inicializar.
if (!desdeFiltro) {
  const idsHermano = new Set();
  try {
    for (const it of ($('Get Precio').all() || [])) {
      if (it && it.json && it.json.variante_id) idsHermano.add(String(it.json.variante_id));
    }
  } catch (e) { /* Get Precio no corrio: no hay nada que descartar */ }
  todo = $input.all().map((i) => i.json)
    .filter((r) => r && r.precio_lista !== undefined)
    .filter((r) => !idsHermano.has(String(r.variante_id)));
}

// ── ELECCION DE VARIANTE (v8.3b: de SQL a codigo) ─────────────────────────
// Un producto trae TODAS sus variantes; hay que quedarse con UNA. Misma escalera que
// tenia Get Precio en su var_rank, con el eco del LLM afuera:
//   1. el cliente nombro los ejes -> la que mas ejes matchea (y ninguno en contra)
//   2. mono-variante -> esa
//   3. default_variante curado -> ese es el trabajo normal
//   4. nada -> la mas barata, que es el piso honesto y lo que ya ordenaba el SQL
// Devolver TODAS cuando el cliente no dijo nada seria 'ambiguo' y mandaria a email:
// justo lo que este rediseño vino a evitar.
// MEDIDA Y PACK. Los 7 ejes de dijoValor no distinguen NADA en 12 productos del
// catalogo (auditoria 2026-07-28): sus variantes se diferencian por la MEDIDA
// (carteles, carton, PVC) o por la CANTIDAD DEL PACK (folletos, puntas,
// perforaciones), y ninguno de los dos estaba en la lista. Como ademas solo 1 de las
// 185 variantes tiene default_variante, el desempate caia siempre en "la mas barata":
// "un cartel de 2 x 1 metro" cotizaba $10.500 (la hoja A3) contra $48.000 reales.
// El dato ya vive curado — 53 variantes con atributos.medida en dos formas fijas:
// {alto, ancho, unidad:'cm'} y {diametro, unidad:'pulg'}. Solo faltaba leerlo.
const medidasDelMensaje = (txt) => {
  const out = [];
  const re = /(\d+(?:[.,]\d+)?)\s*[x\u00d7]\s*(\d+(?:[.,]\d+)?)\s*(cm|mts?|metros?|m)?/gi;
  let m;
  while ((m = re.exec(String(txt || '')))) {
    let x = parseFloat(String(m[1]).replace(',', '.'));
    let y = parseFloat(String(m[2]).replace(',', '.'));
    if (!(x > 0) || !(y > 0)) continue;
    const u = (m[3] || '').toLowerCase();
    // "2 x 1 mt" son metros; "60x90" sin unidad son cm. Sin unidad y con los dos
    // valores <= 10, se asume metros: nadie pide un cartel de 2 x 1 centimetros.
    if (/^m/.test(u) || (!u && x <= 10 && y <= 10)) { x *= 100; y *= 100; }
    out.push([x, y]);
  }
  return out;
};
// Diametro de anillo: "1 pulgada", "1/2", "3/4", "1 1/2". Solo anillado metalico.
const diametrosDelMensaje = (txt) => {
  const out = [];
  let s = String(txt || '');
  let m;
  // Las mixtas van PRIMERO y se BORRAN del texto: si no, "1 1/2" produce tambien el
  // 0,5 de su parte fraccionaria, que es un diametro real del catalogo y por lo tanto
  // un falso positivo (el cliente pidio 1 1/2, no 1/2).
  const reMix = /(\d+)\s+(\d+)\s*\/\s*(\d+)/g;
  while ((m = reMix.exec(s))) out.push(Number(m[1]) + Number(m[2]) / Number(m[3]));
  s = s.replace(/(\d+)\s+(\d+)\s*\/\s*(\d+)/g, ' ');
  const reFrac = /(?:^|[^\d\/])(\d+)\s*\/\s*(\d+)/g;
  while ((m = reFrac.exec(s))) out.push(Number(m[1]) / Number(m[2]));
  const rePulg = /(\d+(?:[.,]\d+)?)\s*(?:pulg\w*|")/gi;
  while ((m = rePulg.exec(s))) out.push(parseFloat(String(m[1]).replace(',', '.')));
  return out;
};
const cantidadesDelMensaje = (txt) => (String(txt || '').match(/\d[\d.]*/g) || [])
  .map((x) => Number(String(x).replace(/\./g, ''))).filter((n) => n >= 1 && n <= 999999);
// Tolerancia 5% + medio centimetro: el cliente dice "1x0.65" y la ficha guarda
// 100 x 65, o redondea 29,7 a 30. Es para CENTIMETROS.
const casiIgual = (x, y) => Math.abs(x - y) <= Math.max(x, y) * 0.05 + 0.5;
// En PULGADAS los valores son 0,75 / 1 / 1,5 y ese medio punto absoluto los hace
// matchear todos entre si (|0,75 - 1| = 0,25 < 0,55), o sea el diametro dejaba de
// discriminar y ganaba el primero de la lista. Los diametros de anillo son valores
// discretos y cortos: se comparan casi exactos.
const casiIgualPulg = (x, y) => Math.abs(x - y) <= 0.06;
const medidaCoincide = (med, pares) => {
  if (!med || !pares.length || med.diametro !== undefined) return false;
  const A = Number(med.alto), B = Number(med.ancho);
  if (!(A > 0) || !(B > 0)) return false;
  // Sin orientacion: la ficha puede tener alto/ancho al reves que el cliente (de
  // hecho la variante "a3" del corrugado los tiene invertidos respecto del resto).
  return pares.some((p) => (casiIgual(p[0], A) && casiIgual(p[1], B)) || (casiIgual(p[0], B) && casiIgual(p[1], A)));
};

const elegirVariante = (vs) => {
  if (!Array.isArray(vs) || vs.length <= 1) return vs || [];
  const msgV = normMsg(decidir.userMessage || '');
  const paresMsg = medidasDelMensaje(decidir.userMessage || '');
  const diamMsg = diametrosDelMensaje(decidir.userMessage || '');
  const cantMsg = cantidadesDelMensaje(decidir.userMessage || '');
  // ¿el eje aplica a ESTE grupo? Si ninguna hermana declara medida, no se puntua.
  const hayMedida = vs.some((w) => atrDe(w).medida && atrDe(w).medida.diametro === undefined);
  const hayDiam = vs.some((w) => atrDe(w).medida && atrDe(w).medida.diametro !== undefined);
  // v9.2 (2026-07-28): SOLO el dato curado. El fallback que leia el primer numero
  // del NOMBRE de la variante convertia medidas en tiers de pack: '35X50 CM' -> 35,
  // '100X 70 CM' -> 100, 'A3' -> 3. Auditoria sobre el catalogo real: 12 productos
  // disparaban hayPack y solo 5 son packs de verdad. En los otros 7 (PVC x2, Carton,
  // Montado sobre carton, Kraft 130, Kraft 300, Vegetal) la CANTIDAD que pide el
  // cliente terminaba eligiendo la MEDIDA: 'cartel pvc de 60x90' + 'necesito 3'
  // cotizaba la A3 a $13.000 contra $35.000 reales (2,69x). Los 5 packs reales
  // (folletos x3, perforaciones, puntas) tienen pack_unidades curado al 100%, asi
  // que exigirlo no rompe ninguno. Verificado por dos pasadas adversariales.
  const packDe = (v) => {
    const at = atrDe(v);
    return (at.pack_unidades !== undefined && at.pack_unidades !== null) ? Number(at.pack_unidades) : null;
  };
  // Pack solo si TODAS tienen cantidad y son DISTINTAS: eso es una escalera de packs.
  const hayPack = vs.every((w) => packDe(w) !== null) && new Set(vs.map(packDe)).size === vs.length;
  const puntuar = (v) => {
    const a = atrDe(v);
    let a_favor = 0, en_contra = 0;
    // MEDIDA: una medida explicita no admite interpretacion, por eso pesa doble.
    if (hayMedida && paresMsg.length) {
      if (medidaCoincide(a.medida, paresMsg)) a_favor += 2;
      else if (a.medida) en_contra++;
    }
    // DIAMETRO (anillado metalico): mismo criterio.
    if (hayDiam && diamMsg.length && a.medida && a.medida.diametro !== undefined) {
      if (diamMsg.some((d) => casiIgualPulg(d, Number(a.medida.diametro)))) a_favor += 2;
      else en_contra++;
    }
    // PACK: se elige el tier EXACTO y, si no existe, el inmediato SUPERIOR — nunca el
    // de abajo. Cotizar el pack de 500 cuando el cliente pidio 3000 es la
    // sub-cotizacion de 4x que este fix vino a arreglar. Si pide mas que el tier mas
    // grande, gana el mas grande (el mostrador arma varios packs).
    if (hayPack && cantMsg.length) {
      const tiers = vs.map(packDe).sort((x, y) => x - y);
      const q = Math.max.apply(null, cantMsg);
      const arriba = tiers.filter((t) => t >= q);
      const objetivo = arriba.length ? arriba[0] : tiers[tiers.length - 1];
      if (packDe(v) === objetivo) a_favor += 2; else en_contra++;
    }
    for (const k of ['tamano', 'faz', 'color', 'acabado', 'cobertura', 'material', 'papel']) {
      const val = a[k];
      if (val === null || val === undefined) continue;
      // ¿el cliente nombro ESTE valor? -> a favor. ¿nombro OTRO valor del mismo eje
      // entre las hermanas? -> en contra (pidio a3 y esta es a4).
      if (dijoValor(msgV, k, val)) { a_favor++; continue; }
      const otros = new Set();
      for (const w of vs) {
        const av = atrDe(w)[k];
        for (const x of (Array.isArray(av) ? av : (av === null || av === undefined ? [] : [av]))) otros.add(x);
      }
      for (const x of otros) {
        if (dijoValor(msgV, k, x)) { en_contra++; break; }
      }
    }
    return { a_favor, en_contra };
  };
  const puntuadas = vs.map((v) => ({ v, ...puntuar(v) }));
  const limpias = puntuadas.filter((p) => p.en_contra === 0);
  const base = limpias.length ? limpias : puntuadas;
  // Desempate, en este orden: mas ejes a favor -> default_variante curado -> mas
  // barata. Se aplica IGUAL con o sin anclas: si el cliente dijo "a color" y quedan
  // simple color y doble color, la faz sigue sin anclar y simple es el default de
  // oficio. Sin este desempate salia un menu por una eleccion que el catalogo ya
  // tenia firmada. El precio como ultimo criterio es la direccion segura: si erramos,
  // erramos por abajo y la puerta abierta ofrece el resto.
  const maxF = Math.max(...base.map((p) => p.a_favor));
  const finalistas = base.filter((p) => p.a_favor === maxF);
  if (finalistas.length === 1) return [finalistas[0].v];
  const def = finalistas.find((p) => atrDe(p.v).default_variante === true);
  if (def) return [def.v];
  // v9.2 (2026-07-28): NO se elige la mas barata. Un empate se muestra como
  // empate — decision de Martin: "no hay uno por defecto, muestra todas".
  // Devolver varias filas hace que `evaluar` marque 'fallback: ambiguo', que es
  // la puerta al menu de rescate; con 14b ese menu ahora dice precios.
  // EXCEPCION — ESCALERA: si alguna hermana cotiza por cantidad, el menu perderia
  // la tabla de rangos (que es la respuesta correcta) y saldrian dos lineas que
  // no dicen nada. Ahi se conserva la reduccion, y como ultimo criterio el precio.
  const hayEscalera = finalistas.some((p) => (Number(p.v.n_reglas_cantidad) || 0) >= 1 || p.v.tiene_override);
  if (hayEscalera) {
    const conPrecio0 = finalistas.filter((p) => Number(p.v.precio_lista) > 0);
    const pool0 = conPrecio0.length ? conPrecio0 : finalistas;
    return [pool0.reduce((a, b) => (Number(a.v.precio_lista) <= Number(b.v.precio_lista) ? a : b)).v];
  }
  return finalistas.map((p) => p.v);
};

const porIdx = {};
for (const r of todo) { const k = Number(r.idx) || 1; (porIdx[k] = porIdx[k] || []).push(r); }
// La reduccion se aplica SOLO a las filas que trajo el filtro (que son todas las
// variantes de cada producto) y agrupa POR PRODUCTO, no por idx: un idx puede traer
// productos DISTINTOS y ese es el 'ambiguo' legitimo — reducirlo a uno seria el bot
// eligiendo por su cuenta entre dos productos que compiten. Las filas de Get Precio
// (2a pasada) no pasan por aca: ahi el SQL ya eligio la variante.
if (desdeFiltro) {
  for (const k of Object.keys(porIdx)) {
