    for (const r of porIdx[k]) {
      const pid = r.producto_id || '?';
      if (!porProducto.has(pid)) porProducto.set(pid, []);
      porProducto.get(pid).push(r);
    }
    const out = [];
    for (const vs of porProducto.values()) out.push(...elegirVariante(vs));
