    // porque un rank mejor gano, el "ganador limpio" puede ser un hijack de sinonimo.
    descartados = Array.from(new Set(rows.filter((r) => (Number(r.match_rank) || 9) !== best)
      .map((r) => String(r.nombre_canonico || '').trim()).filter(Boolean)));
    rows = rows.filter((r) => (Number(r.match_rank) || 9) === best);
