      const pidioDF = /doble\s*faz|\bd\s*\/\s*f\b|frente\s*y\s*dorso|de\s+los\s+dos\s+lados|ambas\s+caras/i.test(decidir.userMessage || '');
      // r6-review H1: SOLO datos de DB — el eco del LLM (variPedida) bypaseaba el
