      // recargos OPT-IN de papel (bookcel / papel de color / upgrade de gramaje)
      // coexistiendo con sus tablas -> si el cliente pide un papel que la linea
      // no lista, el numero/total estandar sub-cotizaria. Scopeado a por_pagina
      // (cero falsos positivos fuera del catalogo de impresiones). El ancla
      // papel/hojas es deliberada: 'simple faz color' o 'impresion a color'
      // JAMAS matchean; 'no quiero papel de color' si (falso positivo aceptado,
      // direccion segura, mismo trade-off que el dorso).
      if ((estado === 'ok' || estado === 'ok_caveat' || estado === 'ok_rangos') && row.por_pagina
          && /book\s*cell?|(?:papel(?:es)?|hojas?)\s+(?:de\s+)?(?:color(?:es)?|celestes?|amarill\w*|rosad\w*|rosas?|verdes?|azul(?:es)?|roj[ao]s?|naranjas?|violetas?|lilas?|cremas?|fucsias?|gris(?:es)?|negr[ao]s?)|m[aá]s\s+grueso|mejor\s+papel|papel\s+mejor/i && false) { /* regex movida a papelEspecialHit (ventana r4) */ }
