  const eje = ORDEN_PUERTA.find((k) => sinAnclar.includes(k) && PUERTA[k]);
  if (hayCompetencia && eje) puerta = { eje, frase: PUERTA[eje] };
}
// ── SUPUESTO DEL TRABAJO NORMAL (default_familia) ────────────────────────
// Si lo cotizado es el default de su familia y el cliente NO lo pidio por su
// nombre, el mensaje dice EN QUE se cotizo antes de abrir la puerta. Sin esto el
// default es silencioso: el cliente recibe un numero y no sabe que hay otras
// opciones ni sobre que base se calculo.
// En idioma de cliente: "en A4, papel comun" — nunca gramaje ni tecnologia (la
// lente de costo del 28 midio que pedir vocabulario de imprenta cuesta turnos).
// Los valores salen del ATRIBUTO de la fila, no de una tabla paralela: si manana
// la curacion mueve el default a otro producto, la frase lo sigue sola.
const CLIENTE_DICE = {
  a4: 'A4', a3: 'A3', 'a3+': 'A3+', a5: 'A5', oficio: 'oficio', ingles: 'inglés',
  obra: 'papel común', ilustracion: 'papel ilustración', opalina: 'opalina',
  kraft: 'papel kraft', vegetal: 'papel vegetal', plastico: 'plástico',
  metalico: 'metálico', bn: 'blanco y negro', color: 'color',
  simple: 'de un solo lado', doble: 'doble faz',
};
// ── CAMBIO DE PRODUCTO ────────────────────────────────────────────────────
// Si el turno anterior cotizó OTRO producto, el mensaje lo dice. Sin esto el
// cliente lee dos precios seguidos y asume que el segundo corrige al primero:
// "Ese precio es promocional llevando 6" (incidente 2026-07-28), donde 'ese
// precio' era el del producto ANTERIOR y la promo costaba otra cosa.
// Determinístico a propósito: el LLM no tiene que inferir la relación entre dos
// montos, que es exactamente donde inventa.
let cambioProd = '';
if (okEstado && row && row.nombre_canonico) {
  let previo = '';
  try {
    // La fila mas reciente de bot.decisiones para esta conversacion que haya
    // resuelto un producto. Las de silencio/opciones lo dejan en null y no cuentan.
    const filas = ($('Get Ruta Cotizador').all() || []).map((i) => i.json);
    for (const f of filas) {
      let s = f && f.senales;
      if (typeof s === 'string') { try { s = JSON.parse(s); } catch (e) { s = null; } }
      const nom = s && s.producto_nombre;
      if (typeof nom === 'string' && nom.trim()) { previo = nom.trim(); break; }
    }
  } catch (e) { previo = ''; }
  const norm = (s) => String(s || '').toLowerCase()
    .replace(/[áéíóúü]/g, (c) => ({ 'á': 'a', 'é': 'e', 'í': 'i', 'ó': 'o', 'ú': 'u', 'ü': 'u' }[c]))
    .replace(/ñ/g, 'n').replace(/\s+/g, ' ').trim();
  const ahora = String(row.nombre_canonico).trim();
  // Solo si HUBO un producto antes y es OTRO. Primer turno de la conversacion:
  // no hay nada que contrastar y la frase seria ruido.
  if (previo && norm(previo) !== norm(ahora)) {
    // El parentesis del nombre es una aclaracion tecnica que en una frase de
    // WhatsApp es ruido ('Lona front brillo (ancho max 1,52 m)'). Se saca.
    // La BARRA no se toca aunque tiente: 6 productos se llaman 'Tacos / Emblocados
    // <medida> <color>' y cortar ahi los colapsa todos a 'Tacos' — el aviso quedaria
    // ambiguo justo cuando su unico laburo es distinguir dos productos.
    const corto = previo.split(' (')[0].trim() || previo;
    cambioProd = ' Ojo que este precio es de otro producto, no del ' + corto + ' que te pasé antes.';
  }
}
let supuesto = '';
if (okEstado && row && atr.default_familia === true) {
  // ¿el cliente lo pidio por su nombre? El SQL ya lo midio sobre el candidato-set.
  let porNombre = false;
  try {
    const c0 = ($('Buscar Candidatos').all() || [])
      .map((i) => i.json).find((r) => r && r.producto_id === row.producto_id);
    porNombre = !!(c0 && c0.por_nombre);
  } catch (e) { porNombre = false; }
  if (!porNombre) {
    // Solo los ejes que el cliente NO nombro: si dijo "a color", no se le repite.
    // Orden fijo tamaño → papel → color: es como lo diria un mostrador.
    // La FAZ queda AFUERA a proposito: 'de un solo lado' es el default universal de
    // una imprenta, decirlo es ruido, y sumaba un cuarto eje que convertia la frase
    // en un ladrillo. Si el cliente quiere doble faz, la puerta ya se lo ofrece.
    const partes = [];
    for (const k of ['tamano', 'papel', 'material', 'color']) {
      if (anclados.includes(k)) continue;
      const v = atr[k]; if (v === null || v === undefined) continue;
      const uno = Array.isArray(v) ? (v.length === 1 ? v[0] : null) : v;
      if (uno === null || uno === undefined) continue; // eje con varias opciones: no es supuesto
      const dicho = CLIENTE_DICE[String(uno).toLowerCase()];
      if (dicho) partes.push(dicho);
