if (cambioProd) reply += cambioProd;
if (supuesto) reply += supuesto;
if (puerta) reply += ' ' + puerta.frase;
// El aviso de canal va UNA vez por CONVERSACION. `avisoDado` (Decidir) lo detecta
// buscando el mail del negocio en los salientes de Chatwoot, y el cierre lo lleva:
// a partir del 2do mensaje no se repite. Solo cuando el mensaje lleva plata.

// F4: extras del campo 'mas' — render deterministico por item, independiente del main.
// Tabla completa de un extra NO se renderiza (dos tablas en un WhatsApp es sopa):
// se ofrece, y el follow-up lo resuelve el flujo single ya calibrado.
for (const { m, ev } of (accionLog === 'repregunto' ? [] : extras)) {
  const vvx = nombreVar(ev.row && ev.row.variante, ev.row && ev.row.nombre_canonico);
  // v8.2: el extra usaba `cadaUno`, que es la unidad del item PRINCIPAL. Dos
  // productos distintos en un mismo mensaje no comparten unidad de venta.
  const cadaUnoX = (ev.row && UNIDAD_FRASE[atrDe(ev.row).unidad_venta]) || 'c/u';
  const packX = !!(ev.row && ev.row.por_pack);
  const qx = !packX && Number.isInteger(m.cantidad) && m.cantidad >= 1 && m.cantidad <= CAP_TOTAL ? m.cantidad : null;
  if (ev.estado === 'ok' || ev.estado === 'ok_caveat') {
    const totalOkX = qx !== null && (ev.estado === 'ok' || (ev.row && ev.row.solo_descuentos === true));
    const montoX = fmt(ev.row.precio_lista) + (ev.estado === 'ok_caveat' && !totalOkX ? CAVEAT : '');
    reply += '\n' + (vvx ? 'La opción ' + vvx + ' de ' : '') + nombreProd(ev, m.producto) + ' sale ' + montoX
      + (totalOkX ? ' ' + cadaUnoX + ' — por ' + qx + ', total estimado ' + fmt(qx * Number(ev.row.precio_lista)) + CAVEAT : '') + '.';
  } else if (ev.estado === 'ok_rangos') {
    let bx = null;
    if (qx !== null && Array.isArray(ev.rangosRaw)) bx = ev.rangosRaw.find((r) => r && qx >= Number(r.minQty) && (r.maxQty === null || r.maxQty === undefined || qx <= Number(r.maxQty))) || null;
    if (bx) reply += '\nEl de ' + nombreProd(ev, m.producto) + ': por ' + qx + ' unidades sale ' + fmt(bx.value) + ' ' + cadaUnoX + ' — total estimado ' + fmt(qx * Number(bx.value)) + CAVEAT + '.';
    else reply += '\nEl de ' + nombreProd(ev, m.producto) + ' va por cantidad; si querés te paso la tabla.';
  } else {
    reply += '\nEl de ' + nombreProd(ev, m.producto) + ' te lo cotiza el equipo por mail.';
  }
}

// v8.2 El aviso de canal se pegaba ANTES de concatenar los items del campo
// `mas`, asi que en un multi-item quedaba en el MEDIO del mensaje. Va al final,
// y sigue siendo una sola vez por conversacion y solo si el mensaje lleva plata.
if (/\$\s?\d/.test(reply) && !decidir.avisoDado) reply += CIERRE;

// El Aclarador (2ª llamada LLM) toma los fallos de RESOLUCION; los fallbacks
// legitimos de 'lo cotiza el equipo' (override/qr_multiple/precio_cero/dorso/
// papel_especial/rangos_invalidos/sql_error) NO pasan por el. Si el anti-loop
// de pass-1 ya derivo a email (accionLog informo_precio), tampoco.
const needsAclarador = !SEGUNDA_PASADA && TRIGGERS_ACLARADOR.includes(estado) && accionLog !== 'informo_precio';
const candidatos = [];
if (needsAclarador) {
  for (const r0 of (main.rows || [])) {
    // v8.2 (r6-review H6a extendido): el rescate de menu ya filtraba nicho, la
    // lista que va al Aclarador no. Por ahi se colaba la promo de inmobiliarias.
    const ni0 = nichoDe(r0.nombre_canonico, r0);
    if (ni0 && !ni0.re.test(ventanaCliente)) continue;
    let g = candidatos.find((x) => x.producto === r0.nombre_canonico);
    if (!g) { g = { producto: r0.nombre_canonico, variantes: [] }; candidatos.push(g); }
    const nv = nombreVar(r0.variante, r0.nombre_canonico);
    if (nv && !g.variantes.includes(nv)) g.variantes.push(nv);
